WITH filtered AS (SELECT *, DATEDIFF(ends_on, starts_on) AS days_starts_on_to_ends_on, CEIL(discount_pct) AS discount_pct_whole FROM promotions WHERE ends_on > DATE '2024-05-06' AND channel IS NOT NULL AND starts_on BETWEEN '2023-05-01' AND '2023-08-29'), attributed AS (SELECT a.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM filtered a LEFT JOIN promotions pr ON a.channel <=> pr.channel AND a.starts_on BETWEEN pr.starts_on AND pr.ends_on), matched_keys AS (SELECT channel FROM attributed INTERSECT SELECT channel FROM promotions WHERE discount_pct BETWEEN 0.31 AND 0.32), verified AS (SELECT s.* FROM attributed s INNER JOIN matched_keys k ON s.channel = k.channel), metrics AS (SELECT id, channel, promo_code, starts_on, ends_on, discount_pct, days_starts_on_to_ends_on, discount_pct_whole, promo_id, promotion_promo_code, promotion_discount_pct, ROUND(promotion_discount_pct / SUM(promotion_discount_pct) OVER (PARTITION BY channel, promotion_promo_code), 4) AS promotion_discount_pct_share, PERCENT_RANK() OVER (PARTITION BY promotion_promo_code, channel ORDER BY promo_id DESC NULLS FIRST) AS promo_id_percent_rank FROM verified), valid AS (SELECT *, GREATEST(promotion_discount_pct_share, discount_pct_whole) AS greatest_promotion_discount_pct_share_discount_pct_whole, CAST(promotion_discount_pct_share AS INT) AS promotion_discount_pct_share_int FROM metrics WHERE starts_on > DATE '2023-06-01'), matched AS (SELECT src.*, pr.id AS promo_id_2, pr.promo_code AS promotion_promo_code_2, pr.discount_pct AS promotion_discount_pct_2 FROM valid src INNER JOIN promotions pr ON COALESCE(src.channel, 'store') = pr.channel AND src.starts_on >= pr.starts_on AND src.starts_on < pr.ends_on + INTERVAL 7 DAYS), base AS (SELECT *, CASE WHEN promotion_promo_code = 'WELCOME5' THEN 1 ELSE 0 END AS is_welcome5, ROUND(promotion_discount_pct_share_int, 0) AS promotion_discount_pct_share_int_rounded FROM matched WHERE ends_on >= DATE '2024-06-11' AND promotion_promo_code_2 IS NOT NULL) SELECT * FROM (SELECT channel, promotion_promo_code_2, promo_code, promo_id FROM base) src PIVOT (AVG(promo_id) AS amount FOR promo_code IN ('SPRING10', 'WELCOME5'));
